esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 loanID, bool direct) public {
        // Since this contract (InvMutTest) is msg.sender for all calls on c, and it is never
        // the lender of any loan (it can never become a lender through any public entry),
        // setDirectRepay reverts iff msg.sender != loans[loanID].lender.
        // For any loanID that indexes a loan where lender != address(this), it reverts.
        // For any loanID that would make loans[loanID].lender == address(this), it completes.
        //
        // The general rule we assert: the call completes (does NOT revert) if and only if
        // the stored lender for that loanID equals address(this).
        //
        // Because address(this) is never a lender in this test, the assertion is simply that
        // the call ALWAYS reverts for every input. This is a non-trivial, breakable rule.

        bool reverted;
        c.setDirectRepay(loanID, direct); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // The caller (this test contract) is not the lender of any loan, so it must revert.
        assert(reverted);
    }
}

